// RUN: %libomp-cxx-compile -fopenmp-version=61 && %libomp-run \
// RUN:   | FileCheck %s --match-full-lines

#ifndef HEADER
#define HEADER

#include <cstdlib>
#include <cstdio>

int main() {
  printf("do\n");
  // The loop generated by 'flatten' is the canonical loop associated with the
  // worksharing 'omp for'. With a single thread the iteration order is the
  // original row-major order.
#pragma omp parallel for num_threads(1)
#pragma omp flatten
  for (int i = 0; i < 2; ++i)
    for (int j = 0; j < 3; ++j)
      printf("i=%d j=%d\n", i, j);
  printf("done\n");
  return EXIT_SUCCESS;
}

#endif /* HEADER */

// CHECK:      do
// CHECK-NEXT: i=0 j=0
// CHECK-NEXT: i=0 j=1
// CHECK-NEXT: i=0 j=2
// CHECK-NEXT: i=1 j=0
// CHECK-NEXT: i=1 j=1
// CHECK-NEXT: i=1 j=2
// CHECK-NEXT: done
